import * as THREE from './vendor/three.module.js';
import {ELEMENTS} from './spells.js';
export class ArenaScene{
constructor(container){this.container=container;this.scene=new THREE.Scene();this.scene.background=new THREE.Color(0x080e1d);this.scene.fog=new THREE.FogExp2(0x0b1329,.018);this.camera=new THREE.PerspectiveCamera(43,container.clientWidth/container.clientHeight,.1,140);this.camera.position.set(0,12.8,20);this.camera.lookAt(0,.3,0);this.renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'high-performance'});this.renderer.setSize(container.clientWidth,container.clientHeight);this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=THREE.PCFSoftShadowMap;this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.renderer.toneMapping=THREE.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.2;container.appendChild(this.renderer.domElement);this.effects=[];this.projectiles=[];this.ambient=[];this.time=0;this.shake=0;this.playerX=0;this.enemyX=0;this.orbTexture=this.createGlow();this.build();this.resize=new ResizeObserver(()=>this.onResize());this.resize.observe(container);}
createGlow(){const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d'),g=ctx.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'rgba(255,255,255,1)');g.addColorStop(.08,'rgba(255,255,255,1)');g.addColorStop(.25,'rgba(255,255,255,.5)');g.addColorStop(.5,'rgba(255,255,255,.13)');g.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=g;ctx.fillRect(0,0,128,128);return new THREE.CanvasTexture(c);}
mat(color,roughness=.8,metalness=.1){return new THREE.MeshStandardMaterial({color,roughness,metalness});}
mesh(geometry,material,x=0,y=0,z=0,parent=this.scene){const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
glow(color,size,x,y,z,parent=this.scene,opacity=.7){const m=new THREE.SpriteMaterial({map:this.orbTexture,color,transparent:true,opacity,depthWrite:false,blending:THREE.AdditiveBlending});const o=new THREE.Sprite(m);o.scale.set(size,size,1);o.position.set(x,y,z);parent.add(o);return o;}
ring(radius,color,y=0,thickness=.025,opacity=.8,parent=this.scene){const m=this.mesh(new THREE.TorusGeometry(radius,thickness,8,128),new THREE.MeshBasicMaterial({color,transparent:true,opacity}),0,y,0,parent);m.rotation.x=Math.PI/2;return m;}
line(points,color,opacity=.6,parent=this.scene){const o=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(...p))),new THREE.LineBasicMaterial({color,transparent:true,opacity}));parent.add(o);return o;}
build(){const s=this.scene;s.add(new THREE.HemisphereLight(0x829ae5,0x242644,2));const moon=new THREE.DirectionalLight(0xa9c1ff,3);moon.position.set(-9,18,-3);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);Object.assign(moon.shadow.camera,{left:-14,right:14,top:14,bottom:-14});s.add(moon);const rim=new THREE.DirectionalLight(0x8f6ff0,2.2);rim.position.set(6,4,-8);s.add(rim);const fill=new THREE.PointLight(0x8663e6,60,24,2);fill.position.set(0,5,-4);s.add(fill);const blue=new THREE.PointLight(0x749dc8,38,20,2);blue.position.set(0,4,5);s.add(blue);
const dark=this.mat(0x172238,.95),stone=this.mat(0x26344a,.88),edge=this.mat(0x4a5263,.78,.25),trim=this.mat(0x756c6a,.7,.4);this.mesh(new THREE.CylinderGeometry(9.6,10.3,.8,64),dark,0,-.65,0);this.mesh(new THREE.CylinderGeometry(9.5,9.7,.18,64),edge,0,-.19,0);this.mesh(new THREE.CylinderGeometry(9.35,9.35,.13,64),stone,0,-.06,0);this.ring(9.28,0x67738d,.045,.035,.45);this.ring(8.85,0x767392,.042,.016,.45);this.ring(8.15,0x7f719c,.045,.035,.45);this.ring(6.95,0x605777,.045,.015,.5);this.ring(6.8,0xb6a3d6,.046,.018,.45);this.ring(6.68,0x625a89,.047,.018,.7);this.ring(4.5,0x685b86,.05,.018,.45);this.ring(1.9,0x8f79b2,.05,.015,.55);this.ring(1.7,0x8f79b2,.05,.015,.35);
for(let i=0;i<48;i++){const angle=i*Math.PI/24,x=Math.sin(angle),z=Math.cos(angle);this.line([[x*6.96,.052,z*6.96],[x*8.14,.052,z*8.14]],0x5b647b,.3);this.line([[x*8.86,.053,z*8.86],[x*9.25,.053,z*9.25]],0xa29cc4,.3);if(i%2===0){const a=angle,rad=7.55,p=[[0,0,-.25],[0,0,.25],[-.18,0,.08],[.18,0,-.08]];const pts=p.map(([px,_,pz])=>[Math.sin(a)*rad+px*Math.cos(a)+pz*Math.sin(a),.065,Math.cos(a)*rad-px*Math.sin(a)+pz*Math.cos(a)]);this.line(pts,0xb0a1cf,.45);}}
for(let i=0;i<6;i++){let a=i*Math.PI/3;this.line([[Math.cos(a)*4.48,.053,Math.sin(a)*4.48],[Math.cos(a+Math.PI*2/3)*4.48,.053,Math.sin(a+Math.PI*2/3)*4.48]],0x7b739f,.28);}
// Separate stone wedges make a readable, weathered arena floor.
for(let i=0;i<16;i++){const a=i*Math.PI/8;this.line([[Math.cos(a)*1.95,.05,Math.sin(a)*1.95],[Math.cos(a)*6.65,.05,Math.sin(a)*6.65]],0x111c30,.7);const box=this.mesh(new THREE.BoxGeometry(1.7,.26,.68),dark,Math.cos(a)*9.26,.11,Math.sin(a)*9.26);box.rotation.y=-a+Math.PI/2;}
for(let i=0;i<8;i++){const angle=(i/8)*Math.PI*2+Math.PI/8,x=Math.cos(angle)*9.3,z=Math.sin(angle)*9.3;this.pillar(x,z,i,stone,dark,trim);}
// Monumental broken gate behind the opponent.
for(const x of [-3.8,3.8]){this.mesh(new THREE.BoxGeometry(.95,7,.95),dark,x,3.1,-8.6);this.mesh(new THREE.BoxGeometry(1.3,.3,1.3),edge,x,6.65,-8.6);for(let y=1;y<6;y+=1.4)this.mesh(new THREE.BoxGeometry(1.02,.1,1.02),edge,x,y,-8.6);this.glow(0x8472df,3,x,4.2,-8.4,s,.22);}
this.portal=new THREE.Group();this.portal.position.set(0,3.45,-8.1);s.add(this.portal);const portalMat=new THREE.MeshBasicMaterial({color:0x8470cb,transparent:true,opacity:.65});this.mesh(new THREE.TorusGeometry(2.22,.025,6,128),portalMat,0,0,0,this.portal);this.mesh(new THREE.TorusGeometry(2.08,.013,6,128),portalMat,0,0,0,this.portal);const aRing=this.mesh(new THREE.TorusGeometry(1.75,.008,4,128),portalMat,0,0,0,this.portal);aRing.rotation.x=.35;for(let i=0;i<12;i++){const a=i*Math.PI/6;const g=this.mesh(new THREE.OctahedronGeometry(.055),portalMat,Math.sin(a)*2.35,Math.cos(a)*2.35,0,this.portal);g.rotation.z=a;this.line([[Math.sin(a)*2,.1+Math.cos(a)*2,.01],[Math.sin(a)*2.22,.1+Math.cos(a)*2.22,.01]],0xaca0e2,.4,this.portal);}this.glow(0x695cb9,8,0,3.5,-8.8,s,.26);
for(let i=0;i<28;i++){const a=i*2.3999,r=18+Math.random()*26,h=3+Math.random()*10;const mountain=this.mesh(new THREE.ConeGeometry(2+Math.random()*3,h,4),this.mat(0x101c32),Math.cos(a)*r,-5+h/2,Math.sin(a)*r-12);mountain.rotation.y=a;}
const starPositions=[];for(let i=0;i<850;i++){starPositions.push((Math.random()-.5)*100,Math.random()*45+4,-Math.random()*80-10);}const starGeo=new THREE.BufferGeometry();starGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPositions,3));s.add(new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xbfc5ff,size:.055,transparent:true,opacity:.75,sizeAttenuation:true})));
this.mesh(new THREE.SphereGeometry(1.5,32,32),new THREE.MeshBasicMaterial({color:0xc6cce4}),-11,16,-35);this.glow(0x9aabea,10,-11,16,-35,s,.23);
this.player=this.mage(0x64709b,0xa793ed,false);this.player.position.set(0,0,4.2);this.enemy=this.mage(0x51446b,0xceacee,true);this.enemy.position.set(0,0,-4.2);this.playerRing=this.ring(.95,0xaaa0da,.085,.025,.75,this.player);this.enemyRing=this.ring(1.15,0xaa79d1,.085,.025,.6,this.enemy);this.playerShield=this.mesh(new THREE.SphereGeometry(1.3,24,16),new THREE.MeshBasicMaterial({color:0x9ccaff,transparent:true,opacity:.085,wireframe:true}),0,1.1,0,this.player);this.playerShield.visible=false;this.enemyShield=this.mesh(new THREE.SphereGeometry(1.4,24,16),new THREE.MeshBasicMaterial({color:0xcda0ff,transparent:true,opacity:.09,wireframe:true}),0,1.1,0,this.enemy);this.enemyShield.visible=false;
for(let i=0;i<45;i++){const o=this.glow(i%3?0x8779c9:0xc7b69b,.06+Math.random()*.13,(Math.random()-.5)*19,Math.random()*4+.2,(Math.random()-.5)*18,s,.5);this.ambient.push({o,offset:Math.random()*10,speed:.1+Math.random()*.3});}}
pillar(x,z,i,stone,dark,trim){const group=new THREE.Group();group.position.set(x,0,z);this.scene.add(group);const h=z>2?1.8:3.2+(i%3)*.45;this.mesh(new THREE.BoxGeometry(1.1,.3,1.1),dark,0,.18,0,group);this.mesh(new THREE.CylinderGeometry(.35,.5,h,6),stone,0,h/2+.3,0,group);this.mesh(new THREE.CylinderGeometry(.58,.45,.22,6),trim,0,h+.35,0,group);this.mesh(new THREE.OctahedronGeometry(.26,0),new THREE.MeshStandardMaterial({color:0xa496ce,emissive:0x9780db,emissiveIntensity:2,roughness:.3,metalness:.6}),0,h+.78,0,group);this.glow(0xac8cec,2,0,h+.8,0,group,.4);const light=new THREE.PointLight(0x9a7bdd,7,5,2);light.position.set(0,h+.8,0);group.add(light);this.line([[0,.5,.36],[0,h-.1,.36]],0xc7b491,.5,group);}
mage(robeColor,glowColor,enemy){const group=new THREE.Group();this.scene.add(group);const robe=this.mat(robeColor,.93),black=this.mat(0x101526,.9),gold=this.mat(0xb6a581,.4,.65),glow=new THREE.MeshStandardMaterial({color:glowColor,emissive:glowColor,emissiveIntensity:1.8});this.mesh(new THREE.CylinderGeometry(.29,.73,1.75,12),robe,0,1.1,0,group);const cape=this.mesh(new THREE.ConeGeometry(.68,1.9,5,1,true),this.mat(enemy?0x342c4d:0x323e5f),0,1.05,enemy?-.1:.1,group);cape.rotation.y=.6;this.mesh(new THREE.SphereGeometry(.4,12,12),black,0,2.24,0,group);const hood=this.mesh(new THREE.SphereGeometry(.47,16,12,0,Math.PI*2,0,Math.PI*.72),robe,0,2.28,enemy?-.05:.05,group);hood.rotation.x=enemy?-.35:.35;const faceZ=enemy?.31:-.31;this.mesh(new THREE.SphereGeometry(.27,12,12),black,0,2.21,faceZ,group);for(let x of [-.1,.1])this.mesh(new THREE.SphereGeometry(.025,6,6),glow,x,2.27,enemy?.56:-.56,group);this.mesh(new THREE.TorusGeometry(.32,.045,6,16),gold,0,1.35,0,group).rotation.x=Math.PI/2;for(let side of [-1,1]){const shoulder=this.mesh(new THREE.SphereGeometry(.25,8,8),robe,side*.36,1.87,0,group);const arm=this.mesh(new THREE.CylinderGeometry(.15,.22,.8,8),robe,side*.49,1.48,0,group);arm.rotation.z=side*.35;this.mesh(new THREE.SphereGeometry(.115,8,8),this.mat(0xaba1a5),side*.64,1.18,enemy?.13:-.13,group);}const staff=this.mesh(new THREE.CylinderGeometry(.035,.045,2.6,8),gold,.83,1.28,0,group);staff.rotation.z=-.08;this.mesh(new THREE.TorusGeometry(.19,.035,6,16),gold,.93,2.65,0,group);this.mesh(new THREE.OctahedronGeometry(.14),glow,.93,2.65,0,group);this.glow(glowColor,1.2,.93,2.65,0,group,.65);for(let i=0;i<3;i++)this.line([[0,1.5,enemy?.34:-.34],[.16,1.25-i*.19,enemy?.43:-.43],[-.16,1.1-i*.19,enemy?.49:-.49]],0xb6a18b,.6,group);group.userData={robe,glow};return group;}
onResize(){const w=this.container.clientWidth,h=this.container.clientHeight;if(!w||!h)return;this.camera.aspect=w/h;this.camera.fov=w<700?53:43;this.camera.updateProjectionMatrix();this.renderer.setSize(w,h);}
setEnemy(color){this.enemy.userData.glow.color.set(color);this.enemy.userData.glow.emissive.set(color);this.enemy.userData.robe.color.set(color).multiplyScalar(.42);}
spawnProjectile(from,element,power=1,duration=.8){const start=from==='player'?this.player:this.enemy,end=from==='player'?this.enemy:this.player;const g=new THREE.Group();this.scene.add(g);const col=ELEMENTS[element].hex;const geom=element==='ice'?new THREE.OctahedronGeometry(.2+power*.04):element==='earth'?new THREE.DodecahedronGeometry(.19+power*.04):new THREE.IcosahedronGeometry(.12+power*.04,1);const core=this.mesh(geom,new THREE.MeshBasicMaterial({color:col}),0,0,0,g);if(element==='ice')core.scale.set(.7,1.8,.7);if(element==='arcane'){const orbit=this.mesh(new THREE.TorusGeometry(.32,.016,6,32),new THREE.MeshBasicMaterial({color:col}),0,0,0,g);orbit.rotation.x=.6;}if(element==='lightning')this.line([[-.2,.45,0],[.15,.15,0],[-.12,0,0],[.2,-.45,0]],0xffeeaa,1,g);this.glow(col,1.7+power*.25,0,0,0,g,.9);const p={g,start:new THREE.Vector3(start.position.x,1.6,start.position.z),end:new THREE.Vector3(end.position.x,1.3,end.position.z),t:0,duration,element,from};g.position.copy(p.start);this.projectiles.push(p);return p;}
removeProjectile(p){if(!p)return;this.disposeObject(p.g);this.projectiles=this.projectiles.filter(x=>x!==p);}
burst(x,z,color=0xb699ed,count=28,power=1){this.shake=Math.min(.16,this.shake+.05*power);for(let i=0;i<count;i++){const o=this.glow(color,.1+Math.random()*.3,x,1.3,z,this.scene,.9);const a=Math.random()*Math.PI*2;this.effects.push({o,life:.4+Math.random()*.65,max:1,v:new THREE.Vector3(Math.cos(a)*(1+Math.random()*2)*power,Math.random()*2,Math.sin(a)*(1+Math.random()*2)*power)});}const ring=this.ring(.25,color,.15,.035,.9);ring.position.x=x;ring.position.z=z;this.effects.push({o:ring,life:.6,max:.6,expand:7*power});}
castAura(element,enemy=false){const target=enemy?this.enemy:this.player;this.burst(target.position.x,target.position.z,ELEMENTS[element].hex,12,.5);}
lightning(enemy=false){const t=enemy?this.player:this.enemy;let p=[];for(let i=0;i<9;i++)p.push([t.position.x+(i===8?0:(Math.random()-.5)*1.5),9-i, t.position.z]);const o=this.line(p,0xe8d9ff,1);this.effects.push({o,life:.3,max:.3});this.burst(t.position.x,t.position.z,0xd4b5ff,40,1.5);}
ultimate(){this.lightning();this.burst(0,0,0xb593ff,80,3);for(let i=0;i<3;i++){const ring=this.ring(.5,0xc6a6ff,.1+i*.15,.045,.95);this.effects.push({o:ring,life:1,max:1,expand:13});}this.shake=.22;}
disposeObject(o){this.scene.remove(o);o.traverse?.(n=>{if(n.geometry)n.geometry.dispose();if(n.material){if(Array.isArray(n.material))n.material.forEach(m=>m.dispose());else n.material.dispose();}});}
clearProjectiles(){for(const p of [...this.projectiles])this.removeProjectile(p);}
projectPosition(x,y,z){const p=new THREE.Vector3(x,y,z).project(this.camera);return{x:(p.x*.5+.5)*this.container.clientWidth,y:(-p.y*.5+.5)*this.container.clientHeight};}
update(dt,state){if(dt<=0){this.renderer.render(this.scene,this.camera);return;}this.time+=dt;const t=this.time;this.playerX+=(state.playerX-this.playerX)*Math.min(1,dt*9);this.player.position.x=this.playerX;this.enemyX+=(state.enemyX-this.enemyX)*Math.min(1,dt*3);this.enemy.position.x=this.enemyX;this.player.position.y=Math.sin(t*1.6)*.025;this.enemy.position.y=.05+Math.sin(t*1.5)*.06;this.enemy.rotation.y=Math.sin(t*.5)*.08;this.player.rotation.z=state.dodging?Math.sin(t*13)*.16:0;this.portal.rotation.z=t*.035;this.playerRing.rotation.z=t*.05;this.enemyRing.rotation.z=-t*.04;this.playerShield.visible=state.shield>0||state.dodging;this.enemyShield.visible=state.enemyShield>0;this.playerShield.rotation.y=t*.2;this.enemyShield.rotation.y=-t*.2;this.enemyRing.material.opacity=state.casting?.5+Math.sin(t*10)*.25:.35;this.enemyRing.scale.setScalar(state.casting?1+Math.sin(t*6)*.08:1);
for(const a of this.ambient){a.o.position.y+=dt*a.speed*.3;if(a.o.position.y>4.4)a.o.position.y=.1;a.o.material.opacity=.3+Math.sin(t+a.offset)*.15;}
for(const p of [...this.projectiles]){p.t+=dt;const q=Math.min(1,p.t/p.duration);p.g.position.lerpVectors(p.start,p.end,q);p.g.position.y+=Math.sin(q*Math.PI)*.6;p.g.rotation.x+=dt*8;p.g.rotation.z+=dt*5;if(Math.random()>.3){const o=this.glow(ELEMENTS[p.element].hex,.2,p.g.position.x,p.g.position.y,p.g.position.z,this.scene,.7);this.effects.push({o,life:.3,max:.3});}if(q>=1)this.removeProjectile(p);}
for(const e of [...this.effects]){e.life-=dt;if(e.life<=0){this.disposeObject(e.o);this.effects.splice(this.effects.indexOf(e),1);continue;}e.o.material.opacity=Math.min(1,e.life/e.max);if(e.v)e.o.position.addScaledVector(e.v,dt);if(e.expand)e.o.scale.addScalar(dt*e.expand);}
this.shake*=.9;this.camera.position.x=(Math.random()-.5)*this.shake;this.camera.position.y=12.8+(Math.random()-.5)*this.shake;this.renderer.render(this.scene,this.camera);}
}
